#include <stdio.h>

int main(void) {
    double n = 1000000.0;
    double bytes = n * 4.0;
    double bw = 10e9;
    double copy_ms = bytes / bw * 1000.0;
    double kernel = 0.2;
    double one = copy_ms + kernel + copy_ms;
    double ten = copy_ms + 10.0 * kernel + copy_ms;
    double share = kernel / one * 100.0;
    printf("copy = %.1f ms\n", copy_ms);
    printf("one iteration = %.1f ms\n", one);
    printf("ten iterations = %.1f ms\n", ten);
    printf("kernel share = %.1f%%\n", share);
    return 0;
}
